/// Capability bits exchanged during the handshake. The negotiated set is the
/// intersection of both sides; anything outside it stays disabled for the
/// session. New capabilities bump protocol_version and add a bit - old peers
/// that do not know the bit simply never use it.
public nonisolated enum Chirp_Gateway_PeerCapability: SwiftProtobuf.Enum, Swift.CaseIterable {
  public typealias RawValue = Int
  case relayReadReceipts // = 0
  case relayTyping // = 1
  case relayPresence // = 2
  case relayOfflineMessages // = 3
  case UNRECOGNIZED(Int)

  public init() {
    self = .relayReadReceipts
  }

  public init?(rawValue: Int) {
    switch rawValue {
    case 0: self = .relayReadReceipts
    case 1: self = .relayTyping
    case 2: self = .relayPresence
    case 3: self = .relayOfflineMessages
    default: self = .UNRECOGNIZED(rawValue)
    }
  }

  public var rawValue: Int {
    switch self {
    case .relayReadReceipts: return 0
    case .relayTyping: return 1
    case .relayPresence: return 2
    case .relayOfflineMessages: return 3
    case .UNRECOGNIZED(let i): return i
    }
  }

  // The compiler won't synthesize support with the UNRECOGNIZED case.
  public static let allCases: [Chirp_Gateway_PeerCapability] = [
    .relayReadReceipts,
    .relayTyping,
    .relayPresence,
    .relayOfflineMessages,
  ]

}

